Q: OutlineGroup with SwiftData A: <p>There are two major changes you need to make to the <code>FileItem</code> in the documentation example work with SwiftData.</p>
<ul>
<li>Add an extra <code>parent</code> property for the inverse relationship. You can use <code>parent == nil</code> as the predicate to fetch only the top-level items.</li>
<li>Add an <code>isFolder</code> attribute to differentiate between folders and non-folders. <code>OutlineGroup</code> takes a key path to <code>[T]?</code> in order to differentiate between &quot;not expandable at all&quot; (<code>nil</code>) and &quot;expandable but no children&quot; (<code>[]</code>). However, in SwiftData there is no such distinction.</li>
</ul>
<pre><code>@Model
class FileItem: CustomStringConvertible {
    var name: String
    @Relationship(inverse: \FileItem.parent)
    var children: [FileItem]
    var parent: FileItem?
    var isFolder: Bool

    // this is the key path we will pass to OutlineGroup
    var outlineGroupChildren: [FileItem]? {
        if isFolder {
            children
        } else {
            nil
        }
    }

    init(name: String, children: [FileItem]? = nil) {
        self.name = name
        self.children = children ?? []
        isFolder = children != nil
    }

    var description: String {
        if isFolder {
            return &quot;📄 \(name)&quot;
        } else {
            return children.isEmpty ? &quot;📂 \(name)&quot; : &quot;📁 \(name)&quot;
        }
    }
}

struct ContentView: View {
    @Query(filter: #Predicate&lt;FileItem&gt; { $0.parent == nil }) private var fileItems: [FileItem]
    @Environment(\.modelContext) var ctx
    var body: some View {
        Button(&quot;Add data&quot;) {
            let data =
            FileItem(name: &quot;users&quot;, children:
                [FileItem(name: &quot;user1234&quot;, children:
                  [FileItem(name: &quot;Photos&quot;, children:
                    [FileItem(name: &quot;photo001.jpg&quot;),
                     FileItem(name: &quot;photo002.jpg&quot;)]),
                   FileItem(name: &quot;Movies&quot;, children:
                     [FileItem(name: &quot;movie001.mp4&quot;)]),
                      FileItem(name: &quot;Documents&quot;, children: [])
                  ]),
                 FileItem(name: &quot;newuser&quot;, children:
                   [FileItem(name: &quot;Documents&quot;, children: [])
                   ])
                ])
            ctx.insert(data)
        }

        List {
            OutlineGroup(fileItems, children: \.outlineGroupChildren) { item in
                Text(&quot;\(item.description)&quot;)
            }
        }
        .padding()
    }
}
</code></pre>
<p>Rename <code>FileItem</code> to <code>Entry</code>, and add some more <code>Entry</code>-specific attributes to the <code>@Model</code> class, and you are basically there.</p>

